import { pgTable, uuid, varchar, timestamp } from 'drizzle-orm/pg-core';
import { authAccounts } from '../../../authentication/infrastructure/persistence/schema.js';
export const userProfiles = pgTable('user_profiles', { id: uuid('id').defaultRandom().primaryKey(), accountId: uuid('account_id').notNull().unique().references(() => authAccounts.id, { onDelete: 'cascade' }), firstName: varchar('first_name', { length: 100 }), lastName: varchar('last_name', { length: 100 }), phone: varchar('phone', { length: 30 }), createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(), updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull() });
